import json
from pathlib import Path
import pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data, get_index_daily_data, get_account_dict

acc = get_account_dict()
assets = list(acc.get('watch_list', []))
MIN_ROWS = 61

def _stock(sym, days=200):
    try: return get_stock_daily_data(sym, days=days)
    except Exception: return None

def _index(sym, days=200):
    try: return get_index_daily_data(sym, days=days)
    except Exception: return None

def _series(df):
    if df is None or 'close' not in df or len(df) < MIN_ROWS: return None
    return pd.Series(df['close'].astype(float), index=pd.to_datetime(df['date']))

frames = {a: _stock(a) for a in assets}
series = {a: _series(f) for a, f in frames.items()}
usable = {a: s.pct_change().rename(a) for a, s in series.items() if s is not None}
print('n_usable:', len(usable), flush=True)
R = pd.concat(usable, axis=1, join='inner').dropna().tail(150)
print('R shape:', R.shape, 'last date:', R.index[-1] if len(R) else None, flush=True)

cp = (1.0+R).cumprod()
mkt = R.mean(axis=1)
rel_mom = (cp.shift(5)/cp.shift(25)-1.0).sub((cp.shift(5)/cp.shift(25)-1.0).median(axis=1), axis=0)
beta_ew = R.rolling(60).cov(mkt).div(mkt.rolling(60).var(), axis=0)
neg = R.clip(upper=0.0)
dvr = -((neg**2).rolling(20).mean()**0.5 / R.rolling(20).std())
mx = R.rolling(20).max()
kurt = R.shift(5).rolling(20).kurt()

ef = _index('EURUSD')
print('EURUSD rows:', 0 if ef is None else len(ef), flush=True)
ec = pd.Series(ef['close'].astype(float), index=pd.to_datetime(ef['date'])) if ef is not None else None
if ec is not None:
    eur_ret = ec.pct_change().reindex(R.index)
    eur_20 = (ec/ec.shift(20)-1.0).reindex(R.index)
    print('eur_ret notna:', int(eur_ret.notna().sum()), 'eur_20 notna:', int(eur_20.notna().sum()), flush=True)
    if eur_ret.notna().sum()>=40 and eur_20.notna().sum()>=40:
        evar = eur_ret.rolling(60).var()
        eurusd_cond = R.rolling(60).cov(eur_ret).div(evar, axis=0)*eur_20
        print('eurusd_cond shape:', eurusd_cond.shape, flush=True)
    else:
        eurusd_cond = None
        print('eurusd_cond None (threshold)', flush=True)
else:
    eurusd_cond = None
    print('eurusd_cond None (no data)', flush=True)

corr_parts = []
for a in R.columns:
    others = [R[a].rolling(60).corr(R[b]) for b in R.columns if b != a]
    corr_parts.append(pd.concat(others, axis=1).mean(axis=1).rename(a))
corr_ew = pd.concat(corr_parts, axis=1)
print('corr_ew shape:', corr_ew.shape, flush=True)

fvals = {
 'rel_mom_20d_skip5': rel_mom, 'beta_ew_60d': beta_ew, 'downside_vol_ratio_20': dvr,
 'max_ret_20d': mx, 'eurusd_beta_cond_60x20': eurusd_cond, 'corr_ew_60': corr_ew, 'kurt_20d_skip5': kurt}
for fid, fr in fvals.items():
    if fr is None:
        print(f'  {fid}: MISSING (None)', flush=True)
    else:
        print(f'  {fid}: shape={fr.shape} last_valid={int(fr.iloc[-1].notna().sum())}', flush=True)
"

