import pandas as pd
from alphacrafter.sim.utils import get_account_dict, get_stock_daily_data, get_index_daily_data

acct = get_account_dict()
assets = list(acct.get('watch_list', []))
cur = {p['symbol']: p for p in acct.get('positions', [])}
total = acct['total_assets']
cur_w = {a: cur[a]['market_value']/total for a in assets}

def _stock(sym, days=200):
    try: return get_stock_daily_data(sym, days=days)
    except Exception: return None
def _index(sym, days=200):
    try: return get_index_daily_data(sym, days=days)
    except Exception: return None

series = {}
for a in assets:
    df = _stock(a)
    if df is None or len(df) < 61: continue
    series[a] = pd.Series(df['close'].astype(float), index=pd.to_datetime(df['date']))
usable = {a: s.pct_change().rename(a) for a, s in series.items()}
R = pd.concat(usable, axis=1, join='inner').dropna().tail(150)
cp = (1.0+R).cumprod(); mkt = R.mean(axis=1)
mom = cp.shift(5)/cp.shift(25)-1.0
rel_mom = mom.sub(mom.median(axis=1), axis=0)
mvar = mkt.rolling(60).var()
beta_ew = R.rolling(60).cov(mkt).div(mvar, axis=0)
neg = R.clip(upper=0.0)
semi = (neg**2).rolling(20).mean()**0.5
tot = R.rolling(20).std()
dvr = -(semi/tot)
mx = R.rolling(20).max()
dfx = _index('DXY')
dc = pd.Series(dfx['close'].astype(float), index=pd.to_datetime(dfx['date']))
dxy_ret = dc.pct_change().reindex(R.index)
