bfx = R.rolling(60).cov(dxy_ret).div(dvar, axis=0)
dxy_cond = -bfx*dxy_20
corr_parts = []
for a in R.columns:
    corr_parts.append(pd.concat([R[a].rolling(60).corr(R[b]) for b in R.columns if b!=a], axis=1).mean(axis=1).rename(a))
corr_ew = pd.concat(corr_parts, axis=1)
kurt = R.shift(5).rolling(20).kurt()
fvals = {'rel_mom_20d_skip5': rel_mom,'beta_ew_60d': beta_ew,'downside_vol_ratio_20': dvr,'max_ret_20d': mx,'dxy_beta_cond_60x20': dxy_cond,'corr_ew_60': corr_ew,'kurt_20d_skip5': kurt}
ens = json.loads(Path('factor_ensemble.json').read_text())
sel = [(it['factor_id'], float(it['weight']), int(it.get('direction',1))) for it in ens['selected_factors']]
def ranks(values, assets):
    valid = sorted((float(v), a) for a,v in values.items() if v is not None and pd.notna(v))
    out = {a: 0.5 for a in assets}
    n = len(valid)
    if not n: return out
    for i,(_,a) in enumerate(valid): out[a] = i/(n-1) if n>1 else 0.5
    return out
score = {a: 0.0 for a in assets}
for fid,w,d in sel:
    fr = fvals[fid]
    rk = ranks(fr.iloc[-1].to_dict(), assets)
    for a in assets: score[a] += w*(d*rk[a])
CAP=0.15
def capped_normalize(w, pref):
    w = {a: max(0.0, float(x)) for a,x in w.items()}
    for _ in range(60):
        excess = sum(max(0.0, x-CAP) for x in w.values())
        w = {a: min(CAP,x) for a,x in w.items()}
        room = [a for a,x in w.items() if x < CAP-1e-12]
        if excess < 1e-12 or not room: break
        den = sum(max(0.0, pref.get(a,0.0)) for a in room)
        for a in room: w[a] += excess*(max(0.0, pref.get(a,0.0))/den if den else 1.0/len(room))
    t = sum(w.values())
    return {a: x/t for a,x in w.items()}
