def_w = {'XAU': 0.70*0.12*3, 'US10Y': 0.15*0.12*3, 'CN10Y': 0.0}
pref = {}
for a in assets:
    pref[a] = def_w.get(a, 0.12) if a in ('XAU','US10Y','CN10Y') else 0.05+0.95*score_rk[a]
target = capped_normalize(dict(pref), pref)
print('target weights vs current:')
turn = 0
for a in assets:
